problems.solution:
def gini(labels):
    n = len(labels)
    if n == 0:
        return 0.0
    counts = {}
    for y in labels:
        counts[y] = counts.get(y, 0) + 1
    return 1 - sum((c / n) ** 2 for c in counts.values())

def best_split(xs, ys):
    n = len(xs)
    values = sorted(set(xs))
    best_t, best_score = None, float('inf')
    for a, b in zip(values, values[1:]):
        t = (a + b) / 2
        left = [y for x, y in zip(xs, ys) if x < t]
        right = [y for x, y in zip(xs, ys) if x >= t]
        score = (len(left) * gini(left) + len(right) * gini(right)) / n
        if score < best_score:
            best_t, best_score = t, score
    return best_t, best_score

tree = {'feature': 0, 'threshold': 50,
        'left': {'label': 'decline'},
        'right': {'feature': 1, 'threshold': 40,
                  'left': {'label': 'approve'},
                  'right': {'label': 'review'}}}

def predict(tree, x):
    node = tree
    while 'label' not in node:
        node = node['left'] if x[node['feature']] < node['threshold'] else node['right']
    return node['label']
